# 查一些并发的数据记录保存的数据
SELECT *
FROM bmos_mes.bm_execute_form_data t1
WHERE EXISTS (
    SELECT 1
    FROM bmos_mes.bm_execute_form_data t2
    WHERE t1.operation_time = t2.operation_time
      AND t1.value = t2.value
      AND t1.field_id = t2.field_id
      AND t1.rev = t2.rev
      AND t1.procedure_step_id = t2.procedure_step_id
      AND t1.id <> t2.id
)
AND t1.operation_time IS NOT NULL
AND t1.value IS NOT NULL;

