CREATE TEMPORARY TABLE temp_ids AS
SELECT id FROM bm_procedure_expression
WHERE procedure_step_model_id IN (
    SELECT bm_procedure_step_model.id
    FROM bm_procedure_step_model
    WHERE procedure_model_id IN (
        SELECT id FROM bm_procedure_model
        WHERE process_id = 1826079331689041920 AND process_version = '06'
    ) AND is_deleted = 0
);

DELETE FROM bm_procedure_expression
WHERE id IN (SELECT id FROM temp_ids);

DROP TEMPORARY TABLE temp_ids;


# 处理12环境重复数据点用到的脚本
DROP  TABLE dp_temp;
create table dp_temp as
select bm_dataset_point.id as 'id',
       (select name from bm_dataset where id = bm_dataset_point.dataset_id) as 'ds_name',
       bm_dataset_point.name as 'component_name',
       bm_dataset_point.dataset_key as 'ds_key',
       bm_dataset_point.dataset_point_key as 'old_dp_key',
       concat(bm_dataset_point.dataset_key, '.', bm_dataset_point.dataset_point_key) as 'old_dp_ds',
       (row_number() over () + 20000) as 'new_dp_key',
       concat(bm_dataset_point.dataset_key, '.', (row_number() over () + 20000)) as 'new_dp_ds'
from (select dataset_point_key, dataset_key, count(1) as c
from bm_dataset_point
where is_deleted = 0
group by dataset_point_key, dataset_key
having c > 1) a left join bm_dataset_point on a.dataset_key = bm_dataset_point.dataset_key and a.dataset_point_key = bm_dataset_point.dataset_point_key
where is_deleted = 0 order by create_time;

select * from dp_temp;
select name,dataset_key from bm_dataset where bm_dataset.dataset_key in (select distinct ds_key from dp_temp);

select *
from bm_dataset where is_deleted = 0 order by create_time desc;


create table dp_temp as
select bm_dataset_point.id as 'id',
       (select name from bm_dataset where id = bm_dataset_point.dataset_id) as 'ds_name',
       bm_dataset_point.name as 'component_name',
       bm_dataset_point.dataset_key as 'ds_key',
       bm_dataset_point.dataset_point_key as 'old_dp_key',
       concat(bm_dataset_point.dataset_key, '.', bm_dataset_point.dataset_point_key) as 'old_dp_ds',
       (row_number() over () + 40000) as 'new_dp_key',
       concat(bm_dataset_point.dataset_key, '.', (row_number() over () + 40000)) as 'new_dp_ds'
from (select dataset_point_key, dataset_key, count(1) as c
from bm_dataset_point
where is_deleted = 0
group by dataset_point_key, dataset_key
having c > 1) a left join bm_dataset_point on a.dataset_key = bm_dataset_point.dataset_key and a.dataset_point_key = bm_dataset_point.dataset_point_key
where is_deleted = 0 order by create_time;

-- 84904
select * from dp_temp order by cast(new_dp_key as signed ) desc;


update bm_dataset_point
left join dp_temp on bm_dataset_point.id = dp_temp.id
set bm_dataset_point.dataset_point_key = dp_temp.new_dp_key
where bm_dataset_point.id in (select id from dp_temp);

