-- 数据集重复数据修复
CREATE TEMPORARY TABLE temp_table AS
SELECT dataset_id, field_id, procedure_step_id, MAX(id) AS max_id
FROM bmos_mes.bm_dataset_point
GROUP BY dataset_id, field_id, procedure_step_id;

-- 删除那些不在临时表中的记录
DELETE FROM bmos_mes.bm_dataset_point
WHERE id NOT IN (SELECT max_id FROM temp_table);

-- 清理临时表
DROP TEMPORARY TABLE temp_table;

show processlist ;

select *
from bm_dataset_point where dataset_point_key = '40001';

select dataset_point_key, count(1) as c
from bm_dataset_point
where is_deleted = 0 group by dataset_point_key having c > 1;

update bm_dataset_point
set bm_dataset_point.dataset_point_key = (select dp_temp.new_dp_key from dp_temp where dp_temp.id = bm_dataset_point.id)
where id in (select id from dp_temp);

show processlist ;